script:
(function () {
  'use strict';
  // Repossession of personal property sold on a deferred-payment basis where the gain was reported in
  // full in the year of sale (installment method not used), following IRS Pub. 537 (2025),
  // "Installment method not used to report original sale".
  //   Basis in the obligation = issue price (the amount realized for the note) + OID or unstated
  //   interest already included in income - principal payments received, for the part of the note
  //   the repossession discharges.
  //   Gain or loss = (FMV of the property + anything else received from the buyer)
  //                  - (basis in the obligation + repossession costs).
  //   A gain is ordinary income (gain on the obligation). A loss is a bad debt: a business bad debt
  //   is deducted as an ordinary loss; a nonbusiness bad debt is a short-term capital loss.
  //   Basis of the repossessed property = its FMV.
  // Verified (Node, scratchpad lkrepo/tests/repo.test.js) with hand-worked figures (Pub. 537 has no
  //   numeric example for this case): $12,000 note, $5,000 principal received, FMV $7,500, costs $300
  //   -> obligation basis $7,000, gain $200; FMV $6,000 -> loss $1,300; half the note discharged ->
  //   basis $3,500, $3,500 of note basis left; $400 OID included -> basis $7,400.
  //   Blank or negative input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function signed(v) { return v < 0 ? '−' + money.format(-v) : money.format(v); }

  function repossess(issue, oid, principal, share, fmv, other, costs) {
    var whole = issue + oid - principal;
    var basis = whole * share;
    var total = basis + costs;
    var value = fmv + other;
    return { whole: whole, basis: basis, remaining: whole - basis, total: total, value: value, result: value - total };
  }

  var IDS = ['rpdResult', 'rpdObligBasis', 'rpdNewBasis', 'rpdRemain', 'rpdNote'];

  function update() {
    var fmv = read('rpdFmv'), issue = read('rpdIssue'), principal = read('rpdPrincipal', true), costs = read('rpdCosts', true),
        other = read('rpdOther', true), oid = read('rpdOid', true), sharePct = read('rpdShare');
    var err = el('rpdError'), msg = '';
    if (isNaN(fmv) || fmv < 0) msg = 'Enter the fair market value of the property you took back ($0 or more).';
    else if (isNaN(issue) || issue <= 0) msg = 'Enter the amount of the buyer’s note when you made the sale.';
    else if ([principal, costs, other, oid].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts cannot be negative.';
    else if (principal > issue + oid) msg = 'Principal received cannot be more than the note amount plus interest included in income.';
    else if (isNaN(sharePct) || sharePct <= 0 || sharePct > 100) msg = 'Enter the share of the note the repossession cancels, above 0% and up to 100%.';
    else if ([fmv, issue, principal, costs, other, oid].some(function (v) { return v > 1e12; })) msg = 'Amounts are too large.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { IDS.forEach(function (id) { setText(id, '–'); }); setText('rpdResultLabel', 'Gain or loss on the repossession'); el('rpdLines').innerHTML = ''; return; }

    var r = repossess(issue, oid, principal, sharePct / 100, fmv, other, costs);
    setText('rpdResultLabel', r.result < 0 ? 'Loss on the repossession (bad debt)' : 'Gain on the repossession');
    setText('rpdResult', money.format(Math.abs(r.result)));
    setText('rpdObligBasis', money.format(r.basis));
    setText('rpdNewBasis', money.format(fmv));
    setText('rpdRemain', money.format(r.remaining));

    var business = el('rpdKind').value === 'business';
    var note;
    if (r.result > 0) note = 'You have a gain of ' + money.format(r.result) + ', taxed as ordinary income: it is gain on the note, not on the property, because you already reported the whole gain on the sale.';
    else if (r.result < 0) note = 'You have a loss of ' + money.format(-r.result) + '. Because the full gain was taxed in the year of sale, it is treated as a bad debt: ' +
      (business ? 'a business bad debt, deductible as an ordinary loss.' : 'a nonbusiness bad debt, deducted as a short-term capital loss on Form 8949.');
    else note = 'The property is worth exactly your basis in the note plus your repossession costs, so there is no gain or loss.';
    if (r.remaining > 0) note += ' The repossession cancels only part of the note; ' + money.format(r.remaining) + ' of basis stays with the rest of it.';
    note += ' Your basis in the property you took back is its fair market value, ' + money.format(fmv) + '.';
    setText('rpdNote', note);

    var lines = [
      ['Note amount when you sold (issue price)', money.format(issue)],
      ['Plus OID or unstated interest included in income', money.format(oid)],
      ['Minus principal payments received', principal > 0 ? '−' + money.format(principal) : money.format(0)],
      ['Basis in the whole note', money.format(r.whole)],
      ['Basis in the part cancelled by the repossession (' + sharePct + '%)', money.format(r.basis)],
      ['Plus repossession costs', money.format(costs)],
      ['Total to recover', money.format(r.total)],
      [other > 0 ? 'Fair market value plus other value received' : 'Fair market value of the property', money.format(r.value)],
      ['Gain or (loss)', signed(r.result)]
    ];
    el('rpdLines').innerHTML = lines.map(function (l) {
      return '<tr><td>' + l[0] + '</td><td>' + l[1] + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rpdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
